-- Generated localized release notes.
local _, namespace = ...
namespace.releaseNotesByLocale = {["deDE"]={["sections"]={{["items"]={"Wenn Forever keinen Realmnamen zurückgibt, werden die kürzlichen Gefährten jetzt trotzdem geladen und neue Gruppenmitglieder gespeichert.","Der bisherige Verlauf bleibt erhalten und wird für deine Charaktere derselben Region zusammengeführt. Pro Spieler zählt der neueste Eintrag. Der Verlauf bleibt privat und speichert weiterhin bis zu 100 Spieler für 90 Tage. Auf Retail und Classic bleibt er nach Realm getrennt."},["title"]="Kürzliche Gefährten"}},["version"]="10.1.2",["welcome"]="Kompatibilitätskorrektur für die kürzlichen Gefährten auf Forever."},["esES"]={["sections"]={{["items"]={"Compañeros recientes vuelve a cargar y registrar jugadores aunque Forever devuelva un nombre de reino vacío.","Tu historial anterior se conserva y se reúne para tus personajes de la misma región, guardando el registro más reciente de cada jugador. Sigue siendo privado, con los mismos límites de 100 jugadores y 90 días. En Retail y Classic, el historial sigue separado por reino."},["title"]="Compañeros recientes"}},["version"]="10.1.2",["welcome"]="Corregida la compatibilidad del historial de compañeros recientes con Forever."},["esMX"]={["sections"]={{["items"]={"La lista de compañeros recientes ahora puede cargar y guardar jugadores aunque Forever no proporcione un nombre de reino.","Conservamos tu historial y lo unimos para tus personajes de la misma región, usando el registro más reciente de cada jugador. Sigue siendo privado y mantiene los límites de 100 jugadores y 90 días. En Retail y Classic, cada reino conserva su historial separado."},["title"]="Compañeros recientes"}},["version"]="10.1.2",["welcome"]="Una corrección para tus compañeros recientes en Forever."},["frFR"]={["sections"]={{["items"]={"La liste des compagnons récents se charge et enregistre de nouveau les joueurs lorsque Forever renvoie un nom de royaume vide.","Votre historique existant est conservé et regroupé pour vos personnages d’une même région, avec l’entrée la plus récente pour chaque joueur. Il reste privé et conserve ses limites de 100 joueurs et de 90 jours. Sur Retail et Classic, les historiques restent séparés par royaume."},["title"]="Compagnons récents"}},["version"]="10.1.2",["welcome"]="Un correctif pour retrouver vos compagnons récents sur Forever."},["itIT"]={["sections"]={{["items"]={"La lista dei compagni recenti ora si carica e registra i giocatori anche quando Forever restituisce un nome del reame vuoto.","La cronologia esistente viene conservata e riunita per i tuoi personaggi della stessa regione, mantenendo il dato più recente per ogni giocatore. Resta privata, con gli stessi limiti di 100 giocatori e 90 giorni. Su Retail e Classic, la cronologia resta separata per reame."},["title"]="Compagni recenti"}},["version"]="10.1.2",["welcome"]="Una correzione per i compagni recenti su Forever."},["koKR"]={["sections"]={{["items"]={"Forever에서 서버 이름이 빈 값으로 반환되어도 최근 동료 목록을 불러오고 플레이어를 기록할 수 있도록 수정했습니다.","기존 기록은 보존되며 같은 지역의 내 캐릭터들이 이용하는 하나의 기록으로 합쳐집니다. 플레이어별로 가장 최근 기록을 유지합니다. 기록은 계속 비공개이며, 최대 100명과 90일의 보관 한도도 그대로입니다. Retail과 Classic에서는 계속 서버별로 기록을 구분합니다."},["title"]="최근 동료"}},["version"]="10.1.2",["welcome"]="Forever의 최근 동료 목록 호환성을 수정했습니다."},["ptBR"]={["sections"]={{["items"]={"A lista de companheiros recentes volta a carregar e registrar jogadores mesmo quando o Forever retorna um nome de reino vazio.","Seu histórico anterior é preservado e reunido para os personagens da mesma região, mantendo o registro mais recente de cada jogador. Ele continua privado, com os mesmos limites de 100 jogadores e 90 dias. No Retail e no Classic, o histórico continua separado por reino."},["title"]="Companheiros recentes"}},["version"]="10.1.2",["welcome"]="Correção de compatibilidade para os companheiros recentes no Forever."},["ruRU"]={["sections"]={{["items"]={"Список недавних спутников теперь загружается и сохраняет игроков, даже если Forever возвращает пустое название игрового мира.","Существующая история сохраняется и объединяется для ваших персонажей в одном регионе. Для каждого игрока остаётся самая свежая запись. История по-прежнему личная; лимиты не изменились: 100 игроков и 90 дней. В Retail и Classic история остаётся отдельной для каждого игрового мира."},["title"]="Недавние спутники"}},["version"]="10.1.2",["welcome"]="Исправлена совместимость списка недавних спутников с Forever."},["zhCN"]={["sections"]={{["items"]={"即使Forever返回的服务器名称为空，近期队友列表也能正常读取并记录玩家了。","原有记录会保留，并合并供你在同一地区的角色使用；每位玩家保留最新的一条记录。历史仍为私人信息，上限仍为100名玩家、保存90天。Retail和Classic仍按服务器分别保存记录。"},["title"]="近期队友"}},["version"]="10.1.2",["welcome"]="修复了Forever中近期队友列表的兼容性问题。"},["zhTW"]={["sections"]={{["items"]={"即使Forever回傳的伺服器名稱為空，近期隊友清單也能正常讀取並記錄玩家。","原有記錄會保留，並合併供你在同一地區的角色使用；每位玩家保留最新的一筆記錄。歷史仍為私人資訊，上限維持100名玩家、保存90天。Retail和Classic仍依伺服器分別保存記錄。"},["title"]="近期隊友"}},["version"]="10.1.2",["welcome"]="修正Forever中近期隊友清單的相容性問題。"}}
